// 内置技能 tooltip 描述汉化（后端 BUILTIN_SKILL_DESCRIPTIONS 表，renderer Kre 取 description 显示悬停气泡）
function injectBuiltinDescZh(content) {
  const MARK = 'LUODA_BUILTIN_DESC_ZH_V1'
  if (content.includes(MARK)) return content
  const pairs = [
    ['"apply-locally": "Synchronize all of this thread\'s changes to your project folder without committing"', '"apply-locally": "把本线程的所有变更同步到你的项目文件夹，不提交"'],
    ['brainstorm: "Think through what could improve this change and give varied suggestions"', 'brainstorm: "思考哪些改进能让本次变更更好，并给出多样化建议"'],
    ['explain: "Build a rich visual HTML explanation and show it in Preview"', 'explain: "生成丰富的可视化 HTML 解释并在 Preview 中展示"'],
    ['learn: "Save non-obvious learnings from this session to AGENTS.md"', 'learn: "把本次会话非显然的经验保存到 AGENTS.md"'],
    ['essential: "Rebuild the smallest grounded patch that fully satisfies the request"', 'essential: "重建完全满足请求的最小落地补丁"'],
    ['"deletion-first": "Delete every part of the change that does not earn its maintenance cost"', '"deletion-first": "删除本次变更中不配承担维护成本的每一部分"'],
    ['"tests-as-contract": "Use a compact behavior contract to simplify both tests and production code"', '"tests-as-contract": "用紧凑的行为契约简化测试和生产代码"'],
    ['"adversarial-fix": "Exercise relevant failure modes and fix only defects the evidence supports"', '"adversarial-fix": "演练相关失败模式，只修复有证据支持的缺陷"'],
    ['overhaul: "Rework a change into its cleanest, strongest final design"', 'overhaul: "把变更重做为最干净、最强健的最终设计"'],
    ['"prove-then-prune": "Prove the real behavior, then remove everything the proof does not justify"', '"prove-then-prune": "先证明真实行为，再删除证明无法自圆其说的部分"'],
    ['"release-proof": "Run a conservative real-path release check without redesigning working code"', '"release-proof": "不做破坏性重设计的前提下，跑一次保守的真实路径发布检查"'],
    ['"maintainer-clarity": "Reduce the changed path\\u2019s cognitive cost after its behavior is proven"', '"maintainer-clarity": "行为被证明后，降低变更路径的认知成本"'],
    ['derisk: "Analyze merge and deployment risk and advise how to reduce it"', 'derisk: "分析合并与部署风险，并给出降低风险的建议"'],
    ['push: "Commit outstanding work and push the branch without opening a pull request"', 'push: "提交未完成的工作并推送分支，不开 PR"'],
    ['simplify: "Cut scope back to what was asked and tidy what remains"', 'simplify: "把范围削减回最初要求，并整理剩下的内容"'],
  ]
  let hit = 0
  for (const [from, to] of pairs) {
    if (content.includes(from)) {
      content = content.split(from).join(to)
      hit++
    }
  }
  if (hit > 0) {
    // 补 6 个缺 description 的内置技能（review/test/commit/open-pr/merge-pr/merge-local），
    // 让 Kre 优先命中 description 中文而非回退长英文 prompt
    const simplifyLine = 'simplify: "把范围削减回最初要求，并整理剩下的内容"'
    if (content.includes(simplifyLine)) {
      const extra = ',\n  review: "对抗性审查本次变更，只修复有证据支持的真实缺陷",\n  test: "验证本次变更在行为上确实正确，而不只是能编译或渲染",\n  commit: "把本次工作以一条清晰、描述性的本地提交保存",\n  "open-pr": "为本次工作创建 PR，推送分支并报告 PR 链接",\n  "merge-pr": "完成本次 PR 的合并，克服冲突与 CI 失败直至合并",\n  "merge-local": "把本线程分支本地合并到主分支，无需远程账户"'
      content = content.split(simplifyLine).join(simplifyLine + extra)
    }
    content += '\n// ' + MARK
    log('  ✔ 内置技能 tooltip 描述：汉化 ' + hit + ' 条（并补齐 6 个缺失描述）')
  }
  return content
}


function patchOrchestrator(orbPath) {
  log('')
  log('→ 处理 orchestrator/orchestrator.js（模型数据 + 会话 + 登录 + 防断）')
  let content = readFileSync(orbPath, 'utf8')
  if (!content.includes('LUODA_CUSTOM_MODEL_REGISTRY_V2_MODULE')) backup(orbPath)
  const before = content
  const orbDir = path.dirname(orbPath)

  // ---- v7.2 版本指纹预检：仅在官方原版（未打补丁）上执行 ----
  // 任一关键锚点缺失 → 版本不兼容 → 跳过整个注入（不写文件）
  // 已打补丁的机器（含 LUODA_CUSTOM_MODEL_REGISTRY_V2_MODULE）幂等跳过，不误报
  if (!content.includes('LUODA_CUSTOM_MODEL_REGISTRY_V2_MODULE')) {
    const missingFp = ORCH_FINGERPRINTS.filter((f) => !content.includes(f))
    if (missingFp.length > 0) {
      log('  ⚠ orchestrator.js 版本与补丁不兼容（缺少版本指纹：' + missingFp.join(' | ') + '）')
      log('    已跳过整个 orchestrator 注入，避免破坏应用（不影响汉化/主题/禁升级等其余补丁）。')
      log('    如确认版本一致仍报此错，请把该电脑的 orchestrator.js 提供给开发者适配。')
      return
    }
  }

  // 顺序：离线通用(ensureSerialized短路) → 登录层打通(ensure短路+authHeader兜底) → 会话防断(含RECYCLE) → authed三态 → 登出铁壁 → 额度解锁 → 注册表 → 桥接 → 多设备并发
  content = injectOfflineAuthGeneric(content)
  content = injectOfflineAuthHeader(content)
  content = injectSessionKeepAlive(content)
  content = injectOfflineAuth(content)
  content = injectLogoutHarden(content)
  content = injectTierUnlock(content)
  // 自定义模型 JSON 校正：把已持久化的 171(要key) 接入点修正为 47(免key)，并补齐种子新增模型
  try { reconcileCustomModels(orbDir) } catch (__rce) { log('  ⚠ custom-models.json 校正失败: ' + (__rce && __rce.message)) }
    content = injectCustomModelRegistry(content, orbDir)
  content = injectBridgeGeneric(content)
  content = injectStreamInterrupt(content)
  content = injectModelAllowlist(content)
  content = injectRetryForever(content)
  content = injectTurnRetry(content)
  content = injectModelApi(content)
  content = injectSkillLabelZh(content)
  content = injectBuiltinDescZh(content)
  content = injectMultiDevice(content)

  if (content !== before) {
    // v7.2 引用完整性校验：注入引用的辅助符号必须有定义，否则拒绝写入（防半注入悬空引用导致启动崩溃）
    if (!checkRefIntegrity(content, 'orchestrator.js')) return
    checkJs(content, 'orchestrator.js')
    writeFileSync(orbPath, content, 'utf8')
    log('  ✔ orchestrator.js 已写入')
  } else {
    log('  ⚠ orchestrator.js 无变更（可能版本不匹配）')
  }
}

// ---------------- checkOnly ----------------
function checkOnly() {
  log('')
  log(`=== Freebuff 补丁状态检测 v${VERSION} ===`)
  const orbPath = path.join(APP_DIR, 'resources', 'orchestrator', 'orchestrator.js')
  const asarPath = path.join(APP_DIR, 'resources', 'app.asar')
  const markers = []
  if (existsSync(orbPath)) {
    const c = readFileSync(orbPath, 'utf8')
    const has = (m) => c.includes(m)
    if (has('LUODA_OFFLINE_GENERIC_V2') && has('LUODA_AUTHHDR_V1') && has('LUODA_SESSION_KEEPALIVE_V1') && has('__luodaSynthAuth') && has('LUODA_LOGOUT_HARDEN_V1') && has('LUODA_TIER_UNLOCK_V1') && has('LUODA_CUSTOM_MODEL_REGISTRY_V2') && has('LUODA_GENERIC_BRIDGE_V2') && has('LUODA_MODEL_ALLOWLIST_V1') && has('LUODA_RETRY_FOREVER_V1') && has('LUODA_TURN_RETRY_V1') && has('LUODA_MODEL_API_V1') && has('LUODA_MULTIDEVICE_V1')) markers.push('orchestrator')
  }
  if (existsSync(asarPath)) {
    const c = readFileSync(asarPath, 'latin1')
    if (c.includes('LUODA_NO_UPDATE')) markers.push('app.asar')
  }
  const assets = findAssetsDir()
  if (assets) {
    const b = findBundle(assets)
    if (b) {
      const c = readFileSync(b, 'utf8')
      if (c.includes('头脑风暴')) markers.push('renderer')
    }
  }
  if (markers.length >= 3) {
    log('补丁完整（' + markers.join(' + ') + '），无需重打。')
    finish(0)
  } else if (markers.length > 0) {
    log('补丁部分缺失（' + markers.join(' + ') + '），建议重跑补丁。')
    finish(1)
  } else {
    log('未检测到补丁标记。')
    finish(2)
  }
}

// ---------------- diagnoseOnly ----------------
function diagnoseOnly() {
  log('')
  log(`=== Freebuff 诊断 v${VERSION} ===`)
  log(`安装目录: ${APP_DIR} (存在: ${existsSync(APP_DIR)})`)
  const orbPath = path.join(APP_DIR, 'resources', 'orchestrator', 'orchestrator.js')
  const asarPath = path.join(APP_DIR, 'resources', 'app.asar')
  if (existsSync(orbPath)) {
    const c = readFileSync(orbPath, 'utf8')
    for (const m of ['LUODA_OFFLINE_GENERIC_V2', 'LUODA_AUTHHDR_V1', 'LUODA_SESSION_KEEPALIVE_V1', '__luodaSynthAuth', 'LUODA_LOGOUT_HARDEN_V1', 'LUODA_TIER_UNLOCK_V1', 'LUODA_CUSTOM_MODEL_REGISTRY_V2', 'LUODA_GENERIC_BRIDGE_V2', 'LUODA_MODEL_ALLOWLIST_V1', 'LUODA_RETRY_FOREVER_V1', 'LUODA_TURN_RETRY_V1', 'LUODA_MODEL_API_V1', 'LUODA_MULTIDEVICE_V1', '__fbKeepAliveAll', '__fbKeepAliveCustom', '8640000000000000', '47.114.75.115']) {
      log(`  orchestrator ${m}: ${(c.match(new RegExp(m, 'g')) || []).length}`)
    }
  } else {
    log('  orchestrator.js 不存在')
  }
  if (existsSync(asarPath)) {
    const c = readFileSync(asarPath, 'latin1')
    log(`  app.asar LUODA_NO_UPDATE: ${(c.match(/LUODA_NO_UPDATE/g) || []).length}`)
  }
  finish(0)
}


