const CSS_PATCHES = [
  ["nativeTheme.themeSource = 'dark'", "nativeTheme.themeSource = 'light'"],
  ['background:#0c0d0f;color:#e6e6e6', 'background:#f5f5f7;color:#1b1b1e'],
  ['.msg{color:#9ca3af}', '.msg{color:#5b5b63}'],
  ["titleBarOverlay: { color: '#0a0a0b', symbolColor: '#9a9aa0', height: 54 }", "titleBarOverlay: { color: '#f5f5f7', symbolColor: '#5b5b63', height: 54 }"],
  ["backgroundColor: '#0c0d0f'", "backgroundColor: '#f5f5f7'"],
]
const LIGHT_ROOT_MARKER = '/* luoda-light-root */'
const LIGHT_ROOT = `
${LIGHT_ROOT_MARKER}
:root, .light { color-scheme: light; }
body, .app, .main, .content, .workspace, .sidebar, .explorer, .panel, .thread, .messages, .message, .input, .composer, .editor { background-color: #f5f5f7 !important; color: #1b1b1e !important; }
.msg, .meta, .hint, .placeholder, .muted { color: #5b5b63 !important; }
input, textarea, .input-area, .prompt-input { background-color: #ffffff !important; color: #1b1b1e !important; border-color: #d0d0d8 !important; }
/* 输入框与内容加宽 1200px */
.composer, .input-wrap, .prompt-wrap, .message-input-wrap { max-width: 1200px !important; }
.thread-content, .message-list, .scroll-region, .conversation { max-width: 1200px !important; }
`
function stripOldLightRoot(css) {
  // 移除旧版浅色块（含旧宽度如 1100px），保留新块
  const startMark = css.indexOf(LIGHT_ROOT_MARKER)
  if (startMark < 0) return css
  const endMark = css.indexOf('\n}', startMark)
  const end = endMark >= 0 ? endMark + 2 : css.length
  return css.slice(0, startMark) + css.slice(end)
}

